function sourcePeaks(buffer){const channels=Array.from({length:buffer.numberOfChannels},(_,i)=>buffer.getChannelData(i)),samples=channels[0],step=Math.ceil(samples.length/Math.min(10000,samples.length)),buckets=Math.ceil(samples.length/step),peaks=new Float32Array(buckets);let peak=0,sum=0;for(let ch=0;ch<channels.length;ch++){const data=channels[ch];for(let i=0;i<data.length;i++){const v=Math.abs(data[i]);peak=Math.max(peak,v);sum+=data[i]*data[i];const k=Math.floor(i/step);if(k<buckets)peaks[k]=Math.max(peaks[k],v)}}return {values:peaks,step,duration:buffer.duration,peak,rms:Math.sqrt(sum/(samples.length*channels.length))}}
