function wavePoint(time){if(!model())return 0;for(const t of M.timeline(model())){if(time>=t.start&&time<=t.end){if(t.clip.muted||!t.clip.sourceId)return 0;const s=sources.get(t.clip.sourceId),p=s?.peaks;if(!p)return 0;const at=t.clip.start+time-t.start;return Math.min(1,p.values[Math.min(p.values.length-1,Math.floor(at/p.duration*p.values.length))]*t.clip.gain)}}return 0}
