function drawMixWave(){const canvas=$('mixCanvas'),p=model()?.mix&&sources.get(model().mix.sourceId)?.peaks;if(!canvas||!p)return;requestAnimationFrame(()=>{const w=canvas.clientWidth,h=canvas.clientHeight;canvas.width=w*2;canvas.height=h*2;const ctx=canvas.getContext('2d');ctx.scale(2,2);ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--wave');ctx.beginPath();for(let x=0;x<w;x+=3){const a=p.values[Math.floor(x/w*p.values.length)]*(h-10)/2;ctx.moveTo(x,h/2-a);ctx.lineTo(x,h/2+a)}ctx.stroke()})}
